  {
    "alert_id": "EX2_001",
    "title": "AKI likely from gastroenteritis, not TDF",
    "message": "Guidelines state that in patients on TDF admitted to hospital, intercurrent illnesses with dehydration or sepsis may cause renal deterioration and TDF may need to be stopped or dose-adjusted. This patient has severe gastroenteritis with dehydration (5 days vomiting/diarrhoea, BP 90/60, dry mucous membranes) and creatinine rising from 0.9 to 2.4. Evidence against TDF being the primary cause: the acute timeline, household contacts with identical illness, urea:creatinine ratio of 24:1 favouring pre-renal AKI, and normal baseline creatinine 6 months ago. Evidence for TDF contribution: TDF is nephrotoxic and could compound dehydration-related injury. The guideline supports temporary TDF interruption during the acute illness, not permanent discontinuation.",
    "issue_type": "toxicity",
    "severity": "high",
    "recommended_action": "Hold TDF temporarily during acute kidney injury and dehydration. Rehydrate with IV fluids, recheck creatinine after recovery, and resume TLD if renal function returns to baseline. Do not permanently discontinue TDF prematurely.",
    "citations": [
      {"page_number": 40, "chunk_id": "sahcs_adult_art_2024__sahcs_adult_art_2024__p40_c2"}
    ]
  },
  {
    "alert_id": "EX2_002",
    "title": "Permanent TDF stop may be premature",
    "message": "Guidelines recommend switching from TDF to ABC + 3TC + DTG when renal impairment develops due to TDF. However, this patient's AKI is acute and strongly linked to gastroenteritis with dehydration (urea:creatinine ratio 24:1, prerenal physiology, household outbreak). Permanent discontinuation is premature before renal recovery is assessed. If creatinine normalises after rehydration, TDF can likely be resumed. If renal function does not recover, then switching to ABC + 3TC + DTG would be guideline-concordant.",
    "issue_type": "plan_review",
    "severity": "moderate",
    "recommended_action": "Defer permanent TDF discontinuation decision until acute illness resolves and creatinine is rechecked post-rehydration. If renal impairment persists, switch to ABC + 3TC + DTG per guideline.",
    "citations": [
      {"page_number": 29, "chunk_id": "sahcs_adult_art_2024__sahcs_adult_art_2024__p29_c1"},
      {"page_number": 40, "chunk_id": "sahcs_adult_art_2024__sahcs_adult_art_2024__p40_c2"}
    ]
  },
  {
    "alert_id": "EX2_003",
    "title": "DTG creatinine rise not relevant here",
    "message": "Guidelines describe a small DTG-related creatinine rise (<30 µmol/L) occurring within the first month of initiation, which does not progress. This patient has been on DTG for 2 years with previously normal creatinine, and the current rise is 133 µmol/L (0.9 to 2.4 mg/dL) — far exceeding the DTG-related threshold and occurring acutely with gastroenteritis. This confirms the AKI is not DTG-related. DTG can be continued if the regimen is maintained or temporarily held with TDF during the acute illness.",
    "issue_type": "toxicity",
    "severity": "low",
    "recommended_action": "Do not attribute the creatinine rise to DTG. DTG does not need to be stopped for renal reasons; if holding ART during acute illness, resume DTG with the regimen once rehydrated.",
    "citations": [
      {"page_number": 7, "chunk_id": "sahcs_adult_art_2024__sahcs_adult_art_2024__p7_c1"}
    ]
  }
]
